package dev.zomboid.clans;
import java.util.*;import dev.zomboid.clans.ClanState.*;
/** Server-authoritative wars; all original claim permissions remain below the added gates. */
public final class Clans {
 private static final String BASE="me.danialisntcool.factionfriction.";
 private static final Map<Object,ClanState> states=new WeakHashMap<>();
 public static ClanState state(Object manager){return states.computeIfAbsent(manager,k->new ClanState());}
 public static void bind(Object manager,Object server){state(manager).server=new java.lang.ref.WeakReference<>(server);}
 static Object manager(Object server){Object m=R.call(R.type(BASE+"data.FactionManager"),"get",server);bind(m,server);return m;}
 static UUID id(Object entity){return (UUID)R.call(R.type(BASE+"compat.switchy.SwitchyIdentity"),"id",entity);}
 static UUID fid(Object f){return (UUID)R.call(f,"getId");}
 static Object faction(Object manager,UUID id){return R.call(manager,"getFactionById",id);}
 @SuppressWarnings("unchecked") static Map<UUID,Object> factions(Object m){return (Map<UUID,Object>)R.call(m,"getFactions");}
 @SuppressWarnings("unchecked") static Map<UUID,Object> members(Object f){return (Map<UUID,Object>)R.call(f,"getMembers");}
 static Object mine(Object m,Object p){return R.call(m,"getFactionByPlayer",id(p));}
 static Object wd(Object f){return R.call(f,"getWarData");}
 static long now(Object server){return R.lng(R.call(R.call(server,"overworld"),"getGameTime"));}
 static boolean authority(Object f,Object p){return f!=null&&R.yes(R.call(R.type(BASE+"util.WarOperationUtil"),"isAuthority",members(f).get(id(p))));}
 static void dirty(Object m){R.call(m,"setDirty");}
 static void say(Object p,String text){R.call(R.type(BASE+"network.NotificationUtil"),"send",p,R.call(R.type("net.minecraft.network.chat.Component"),"literal",text));}
 static void notify(Object server,Object f,String text){if(f==null)return;for(UUID u:members(f).keySet()){Object p=online(server,u);if(p!=null){say(p,text);R.call(R.type(BASE+"event.ChatEventHandler"),"syncFactionToClient",p);}}}
 static Object online(Object server,UUID id){return R.call(R.type(BASE+"compat.switchy.SwitchyIdentity"),"online",server,id);}
 public static boolean onlineRequirement(Object f,Object server){if(f==null||server==null)return false;for(UUID u:members(f).keySet())if(online(server,u)!=null)return true;return false;}
 static int onlineCount(Object f,Object server){int n=0;for(UUID u:members(f).keySet())if(online(server,u)!=null)n++;return n;}
 public static void declare(Object player,String target,String reason){action(player,new ClanPacket(ClanPacket.DECLARE,target,reason,1));}
 public static void legacyRaid(Object packet,Object context){R.call(context,"enqueueWork",(Runnable)()->startLegacy(R.call(context,"player"),String.valueOf(R.get(packet,"enemyName"))));}
 public static void legacySurrender(Object packet,Object context){R.call(context,"enqueueWork",(Runnable)()->action(R.call(context,"player"),new ClanPacket(ClanPacket.SURRENDER,"","",0)));}
 public static void operationLaunched(Object player){Object server=R.call(player,"getServer"),m=manager(server),f=mine(m,player);if(f==null)return;Object op=R.get(wd(f),"activeOperation");if(op!=null&&String.valueOf(R.get(op,"state")).equals("PREPARING")){R.set(op,"prepTimeRemaining",0);dirty(m);}}
 public static void capitalCaptured(Object server,Object m,Object attacker,Object defender){War w=state(m).war(fid(attacker));if(w!=null){w.add(fid(attacker),ClanConfig.INSTANCE.capturePoints);finish(server,m,w,fid(attacker),"Capital capturada");}}
 public static void startLegacy(Object player,String target){Object server=R.call(player,"getServer"),m=manager(server),f=mine(m,player);if(f!=null&&state(m).war(fid(f))!=null)say(player,"La guerra ya está declarada. Usa el mapa de operaciones después de la preparación.");else action(player,new ClanPacket(ClanPacket.DECLARE,target,"",1));}
 public static void action(Object player,ClanPacket packet){if(player==null)return;Object server=R.call(player,"getServer"),m=manager(server),f=mine(m,player);ClanState s=state(m);long time=now(server);UUID account=(UUID)R.call(player,"getUUID");
  if(packet.action()==8||packet.action()==9){Nexus.action(player,packet.action()==9);return;}if(packet.action()==6||packet.action()==7){Pve.action(player,packet.action()==7);return;}if(packet.action()==ClanPacket.STATUS){long last=s.requests.getOrDefault(account,Long.MIN_VALUE/2);if(time-last<20)return;s.requests.put(account,time);snapshot(player,m);return;}
  if(!authority(f,player)){say(player,"Solo la jefatura o un comandante puede realizar esta acción.");return;}
  if(packet.action()==ClanPacket.DECLARE){if(R.yes(R.call(R.get(R.type(BASE+"config.FFConfig"),"ADMIN_APPROVED_JUSTIFICATIONS"),"get"))&&!R.yes(R.call(player,"hasPermissions",3))){say(player,"Este servidor exige aprobación administrativa: un administrador debe autorizar la declaración.");return;}Object other=R.call(m,"getFactionByNameOrSlug",ClanState.clean(packet.a(),32));if(other==null||fid(other).equals(fid(f))){say(player,"Elige otro clan válido.");return;}War existing=s.war(fid(f));if(existing!=null||s.war(fid(other))!=null||R.get(wd(f),"enemyFactionId")!=null||R.get(wd(other),"enemyFactionId")!=null){say(player,"Uno de los clanes ya está en un conflicto.");return;}
   @SuppressWarnings("unchecked") Set<UUID> allies=(Set<UUID>)R.call(f,"getAllies");if(allies.contains(fid(other))||R.lng(R.call(f,"getAllianceBreakCooldownEnd",fid(other)))>System.currentTimeMillis()){say(player,"No puedes declarar guerra a un aliado o durante la tregua tras romper la alianza.");return;}
   if(s.profile(fid(f)).cooldowns.getOrDefault(fid(other),0L)>time){say(player,"Hay una tregua entre estos clanes tras el último conflicto.");return;}
   War w=new War();w.a=fid(f);w.b=fid(other);w.siege=packet.value()==1;w.ready=time+ClanConfig.INSTANCE.prepTicks;w.end=w.ready+ClanConfig.INSTANCE.durationTicks;s.wars.put(w.id,w);
   for(Object side:List.of(f,other)){Object war=wd(side);R.set(war,"enemyFactionId",w.enemy(fid(side)));R.set(war,"isWarActive",true);R.set(war,"isRaidActive",false);R.set(war,"isJustifying",false);R.set(war,"justificationReadyTime",0L);R.set(war,"kills",0);R.set(war,"landGained",0);R.set(war,"landLost",0);R.set(war,"playersKilled",0);R.call(side,"addConflictHistory",(w.siege?"Asedio":"Escaramuza")+" contra "+R.call(side==f?other:f,"getName")+": "+ClanState.clean(packet.b(),128));}
   dirty(m);String text=(w.siege?"ASEDIO":"ESCARAMUZA")+": "+R.call(f,"getName")+" vs "+R.call(other,"getName")+". Preparación: "+ClanConfig.INSTANCE.prepTicks/1200+" minutos. "+(w.siege?"Se exige un defensor conectado para dañar o capturar territorio.":"Los territorios permanecen protegidos.");notify(server,f,text);notify(server,other,text);
  }else if(packet.action()==ClanPacket.PROFILE){Profile p=s.profile(fid(f));String[] choices=packet.b().split("\\|",-1);Set<String> badges=Set.of("RADIO","SKULL","MEDIC","TOOLS","STARS");Set<String> doctrines=Set.of("Supervivientes","Nómadas","Milicia","Rescatistas","Recolectores");if(choices.length!=2||!badges.contains(choices[0])||!doctrines.contains(choices[1])){say(player,"Emblema o identidad no válidos.");return;}p.motto=ClanState.clean(packet.a(),96);p.badge=choices[0];p.doctrine=choices[1];dirty(m);notify(server,f,"Identidad del clan actualizada.");
  }else if(packet.action()==ClanPacket.SURRENDER){War w=s.war(fid(f));if(w!=null)finish(server,m,w,w.enemy(fid(f)),"Rendición");
  }else if(packet.action()==ClanPacket.CLAIM){claim(player,m,f);}
  snapshot(player,m);
 }
 public static Object operationTier(Object f){return R.get(R.type(BASE+"faction.FactionTier"),"COLONY");}
 public static boolean canLaunch(Object player,boolean draft){if(!Limits.launch(player))return false;Object server=R.call(player,"getServer"),m=manager(server),f=mine(m,player);if(!authority(f,player))return false;War w=state(m).war(fid(f));if(w==null||!w.siege){say(player,"Solo una guerra de asedio permite operaciones territoriales.");return false;}if(draft)return true;if(now(server)<w.ready){say(player,"Preparación pendiente: "+Math.max(1,(w.ready-now(server)+19)/20)+" segundos.");return false;}Object d=faction(m,w.enemy(fid(f)));if(!onlineRequirement(d,server)){say(player,"Asedio bloqueado: ningún miembro defensor está conectado.");return false;}return true;}
 public static boolean territoryAllowed(Object m,UUID defender){ClanState s=state(m);Object server=s.server.get(),d=faction(m,defender);if(!onlineRequirement(d,server))return false;War w=s.war(defender);return w!=null&&w.siege&&now(server)>=w.ready&&now(server)<w.end;}
 public static boolean operationAllowed(Object op){if(op==null)return false;UUID defender=(UUID)R.get(op,"defenderFactionId");for(Map.Entry<Object,ClanState> e:states.entrySet()){War w=e.getValue().war(defender);if(w!=null&&(w.a.equals(R.get(op,"attackerFactionId"))||w.b.equals(R.get(op,"attackerFactionId"))))return territoryAllowed(e.getKey(),defender);}return false;}
 public static boolean operationTick(Object server,Object manager,Object attacker){bind(manager,server);Object op=R.get(wd(attacker),"activeOperation");if(op==null)return true;String stage=String.valueOf(R.get(op,"state"));if(stage.equals("ABORTING"))return true;boolean allowed=operationAllowed(op);ClanState s=state(manager);UUID key=(UUID)R.get(op,"id");if(!allowed&&s.pausedOperations.add(key)){notify(server,attacker,"Asedio en pausa: el territorio defensor está protegido hasta que vuelva un miembro.");}else if(allowed&&s.pausedOperations.remove(key)){notify(server,attacker,"Un defensor se ha conectado: el asedio puede continuar.");}return allowed;}
 public static void death(Object event){if(R.yes(R.call(event,"isCanceled")))return;Object victim=R.call(event,"getEntity");if(!R.type("net.minecraft.server.level.ServerPlayer").isInstance(victim))return;Object killer=R.call(R.call(event,"getSource"),"getEntity");if(killer==null||!R.type("net.minecraft.server.level.ServerPlayer").isInstance(killer)||killer==victim)return;Object server=R.call(victim,"getServer"),m=manager(server),a=mine(m,killer),b=mine(m,victim);if(a==null||b==null||fid(a).equals(fid(b)))return;War w=state(m).war(fid(a));long time=now(server);if(w==null||!w.enemy(fid(a)).equals(fid(b))||time<w.ready||time>=w.end)return;UUID account=(UUID)R.call(victim,"getUUID");ClanConfig cfg=ClanConfig.INSTANCE;if(time-w.lastVictim.getOrDefault(account,Long.MIN_VALUE/2)<cfg.killCooldownTicks||w.victimCount.getOrDefault(account,0)>=cfg.maxVictimKills)return;w.lastVictim.put(account,time);w.victimCount.merge(account,1,Integer::sum);w.add(fid(a),cfg.killPoints);R.set(wd(a),"kills",((Number)R.get(wd(a),"kills")).intValue()+1);dirty(m);notify(server,a,"+"+cfg.killPoints+" puntos: baja enemiga. Marcador "+w.score(fid(a))+" : "+w.score(fid(b)));
 }
 public static void captured(Object m,Object attacker,Object defender,long chunk){War w=state(m).war(fid(attacker));if(w!=null&&w.siege&&w.enemy(fid(attacker)).equals(fid(defender))&&w.objectives.add("C:"+fid(attacker)+":"+chunk)){w.add(fid(attacker),ClanConfig.INSTANCE.capturePoints);dirty(m);}}
 public static void operationEnded(Object server,Object m,Object a,Object b,Object op){if(b==null||!String.valueOf(R.get(op,"state")).equals("ACTIVE"))return;War w=state(m).war(fid(a));if(w==null||!w.siege)return;@SuppressWarnings("unchecked") List<Object> attacks=(List<Object>)R.get(op,"attacks");for(Object attack:attacks)if(String.valueOf(R.get(attack,"state")).equals("DEFENDED")&&w.objectives.add("D:"+R.get(op,"id")+":"+R.call(attack,"chunkLong")))w.add(fid(b),ClanConfig.INSTANCE.defensePoints);dirty(m);}
 public static void tick(Object server){Pve.tick(server);Object m=manager(server);ClanState s=state(m);long time=now(server);
  for(Object f:new ArrayList<>(factions(m).values())){Object nativeWar=wd(f);UUID enemy=(UUID)R.get(nativeWar,"enemyFactionId");if(enemy==null||s.war(fid(f))!=null||!(R.yes(R.get(nativeWar,"isWarActive"))||R.yes(R.get(nativeWar,"isRaidActive"))||R.yes(R.get(nativeWar,"isJustifying"))))continue;Object d=faction(m,enemy);if(d==null||!Objects.equals(R.get(wd(d),"enemyFactionId"),fid(f))||s.war(enemy)!=null)continue;War migrated=new War();migrated.a=fid(f);migrated.b=enemy;migrated.siege=true;migrated.ready=time+ClanConfig.INSTANCE.prepTicks;migrated.end=migrated.ready+ClanConfig.INSTANCE.durationTicks;s.wars.put(migrated.id,migrated);for(Object side:List.of(f,d)){R.set(wd(side),"isWarActive",true);R.set(wd(side),"isRaidActive",false);R.set(wd(side),"isJustifying",false);notify(server,side,"Conflicto existente adaptado a asedio: "+ClanConfig.INSTANCE.prepTicks/1200+" minutos de preparación. Los puntos nuevos empiezan en cero.");}dirty(m);}
  for(War w:new ArrayList<>(s.wars.values())){Object a=faction(m,w.a),b=faction(m,w.b);if(a==null||b==null){finish(server,m,w,null,"Clan disuelto");continue;}if(!Objects.equals(R.get(wd(a),"enemyFactionId"),w.b)||!Objects.equals(R.get(wd(b),"enemyFactionId"),w.a)){finish(server,m,w,null,"Paz acordada");continue;}if(time>=w.end)finish(server,m,w,w.scoreA==w.scoreB?null:w.scoreA>w.scoreB?w.a:w.b,"Tiempo agotado");}
 }
 static void finish(Object server,Object m,War w,UUID winner,String reason){ClanState s=state(m);if(s.wars.remove(w.id)==null)return;long time=now(server);for(UUID clan:List.of(w.a,w.b)){Object f=faction(m,clan);Profile p=s.profile(clan);p.cooldowns.put(w.enemy(clan),time+ClanConfig.INSTANCE.pairCooldownTicks);int own=w.score(clan),other=w.score(w.enemy(clan));int bundles=ClanState.rewardBundles(own,other,clan.equals(winner),ClanConfig.INSTANCE);if(f==null||reason.equals("Clan disuelto"))bundles=0;for(Map.Entry<String,Integer> item:ClanConfig.INSTANCE.bundle.entrySet())if(bundles>0)p.rewards.merge(item.getKey(),item.getValue()*bundles,(x,y)->Math.min(100000,x+y));p.lastResult=reason+" | "+(winner==null?"Empate":clan.equals(winner)?"Victoria":"Derrota")+" | "+own+":"+other+" | "+bundles+" lotes";if(f!=null){Object op=R.get(wd(f),"activeOperation");if(op!=null)R.set(op,"state",R.get(R.type(BASE+"faction.OperationData$State"),"COMPLETED"));R.call(wd(f),"reset");R.call(f,"addConflictHistory",p.lastResult);notify(server,f,p.lastResult);}}dirty(m);}
 static void claim(Object player,Object m,Object f){Profile p=state(m).profile(fid(f));int delivered=0;Object inv=R.call(player,"getInventory");for(Map.Entry<String,Integer> entry:new ArrayList<>(p.rewards.entrySet())){Object loc=R.call(R.type("net.minecraft.resources.ResourceLocation"),"parse",entry.getKey());Object registry=R.get(R.type("net.minecraft.core.registries.BuiltInRegistries"),"ITEM");Object item=R.call(registry,"get",loc);if(item==R.get(R.type("net.minecraft.world.item.Items"),"AIR"))continue;int max=((Number)R.call(R.make("net.minecraft.world.item.ItemStack",item,1),"getMaxStackSize")).intValue();int count=Math.min(entry.getValue(),max);Object stack=R.make("net.minecraft.world.item.ItemStack",item,count);R.call(inv,"add",stack);int remaining=((Number)R.call(stack,"getCount")).intValue();int given=count-remaining;if(given>0){delivered+=given;int rest=entry.getValue()-given;if(rest==0)p.rewards.remove(entry.getKey());else p.rewards.put(entry.getKey(),rest);dirty(m);}}say(player,delivered>0?"Recibiste "+delivered+" objetos. Lo restante permanece en el depósito del clan.":"No hay espacio, no hay recompensas o falta un mod de los objetos configurados.");}
 public static void snapshot(Object player,Object m){Object server=R.call(player,"getServer"),f=mine(m,player);ClanState s=state(m);long time=now(server);StringBuilder out=new StringBuilder();out.append(ClanState.row("CONFIG",String.valueOf(ClanConfig.INSTANCE.prepTicks/1200),String.valueOf(ClanConfig.INSTANCE.durationTicks/1200),String.valueOf(Limits.rule("ATTACK_BLOCKS_REQUIRED",50)),String.valueOf(Limits.rule("ATTACK_CAPTURE_TIME_SECONDS",60)),String.valueOf(Limits.rule("ATTACK_DEFENSE_TIME_SECONDS",120))));
  out.append(ClanState.row("SELF",String.valueOf(R.coord(player,"X")),String.valueOf(R.coord(player,"Y")),String.valueOf(R.coord(player,"Z")),String.valueOf(R.call(R.call(R.call(player,"level"),"dimension"),"location"))));
  if(f!=null){Pve.snapshot(m,f,out);out.append(ClanState.row("LAND",String.valueOf(Limits.level(R.call(f,"getTier"))),String.valueOf(R.call(f,"getClaimCount")),String.valueOf(Limits.maximum(R.call(f,"getTier")))));Profile p=s.profile(fid(f));out.append(ClanState.row("CLAN",String.valueOf(fid(f)),String.valueOf(R.call(f,"getName")),String.valueOf(R.call(f,"getSlug")),String.valueOf(R.call(f,"getColor")),p.motto,p.badge,p.doctrine,String.valueOf(authority(f,player)),p.lastResult));War w=s.war(fid(f));if(w!=null){Object enemy=faction(m,w.enemy(fid(f)));out.append(ClanState.row("WAR",enemy==null?"Clan disuelto":String.valueOf(R.call(enemy,"getName")),w.siege?"Asedio":"Escaramuza",String.valueOf(Math.max(0,(w.ready-time+19)/20)),String.valueOf(Math.max(0,(w.end-time+19)/20)),String.valueOf(w.score(fid(f))),String.valueOf(w.score(w.enemy(fid(f)))),String.valueOf(enemy!=null&&onlineRequirement(enemy,server))));}
   for(Map.Entry<String,Integer> item:p.rewards.entrySet())out.append(ClanState.row("REWARD",item.getKey(),String.valueOf(item.getValue())));
   for(UUID u:members(f).keySet()){Object member=online(server,u);if(member==null)continue;Object profile=R.call(member,"getGameProfile"),dim=R.call(R.call(R.call(member,"level"),"dimension"),"location");out.append(ClanState.row("MATE",String.valueOf(R.call(profile,"getName")),String.valueOf(R.coord(member,"X")),String.valueOf(R.coord(member,"Y")),String.valueOf(R.coord(member,"Z")),dim.toString(),String.valueOf(members(f).get(u))));}}
  int count=0;for(Object other:factions(m).values()){if(count++>=128)break;out.append(ClanState.row("LIST",String.valueOf(R.call(other,"getName")),String.valueOf(R.call(other,"getSlug")),String.valueOf(members(other).size()),String.valueOf(onlineCount(other,server)),state(m).profile(fid(other)).doctrine));}
  R.call(R.type(BASE+"network.FFNetwork"),"sendToPlayer",player,new ClanPacket(ClanPacket.SYNC,out.length()>30000?out.substring(0,out.lastIndexOf("\n",30000)+1):out.toString(),"",0));
 }
 public static void save(Object m,Object tag){Object data=R.make("net.minecraft.nbt.CompoundTag"),profiles=R.make("net.minecraft.nbt.ListTag"),wars=R.make("net.minecraft.nbt.ListTag");ClanState s=state(m);for(Map.Entry<UUID,Profile> entry:s.profiles.entrySet()){Object t=R.make("net.minecraft.nbt.CompoundTag");Profile p=entry.getValue();put(t,"UUID",entry.getKey());put(t,"Motto",p.motto);put(t,"Badge",p.badge);put(t,"Doctrine",p.doctrine);put(t,"Result",p.lastResult);put(t,"NexusIssued",p.nexusIssued);put(t,"NexusPlaced",p.nexusPlaced);put(t,"NexusPos",p.nexusPos);put(t,"NexusUpgrade",p.nexusUpgrade);put(t,"PveXp",p.pveXp);put(t,"PveWins",p.pveWins);put(t,"PveNext",p.pveNext);put(t,"PveOffer",p.offer);put(t,"PveOfferEnd",p.offerEnd);Object rewards=R.make("net.minecraft.nbt.CompoundTag");for(var e:p.rewards.entrySet())put(rewards,e.getKey(),e.getValue());R.call(t,"put","Rewards",rewards);Object cooldowns=R.make("net.minecraft.nbt.CompoundTag");for(var e:p.cooldowns.entrySet())put(cooldowns,e.getKey().toString(),e.getValue());R.call(t,"put","Cooldowns",cooldowns);R.call(profiles,"add",t);}for(War w:s.wars.values()){Object t=R.make("net.minecraft.nbt.CompoundTag");put(t,"Id",w.id);put(t,"A",w.a);put(t,"B",w.b);put(t,"Siege",w.siege);put(t,"Ready",w.ready);put(t,"End",w.end);put(t,"ScoreA",w.scoreA);put(t,"ScoreB",w.scoreB);Object victims=R.make("net.minecraft.nbt.ListTag");for(var e:w.lastVictim.entrySet()){Object v=R.make("net.minecraft.nbt.CompoundTag");put(v,"Id",e.getKey());put(v,"Time",e.getValue());put(v,"Count",w.victimCount.getOrDefault(e.getKey(),0));R.call(victims,"add",v);}R.call(t,"put","Victims",victims);Object objectives=R.make("net.minecraft.nbt.CompoundTag");for(String o:w.objectives)put(objectives,o,true);R.call(t,"put","Objectives",objectives);R.call(wars,"add",t);}R.call(data,"put","Profiles",profiles);R.call(data,"put","Wars",wars);R.call(tag,"put","ZomboidClansV1",data);}
 static void put(Object tag,String key,Object value){String method=value instanceof UUID?"putUUID":value instanceof Boolean?"putBoolean":value instanceof Integer?"putInt":value instanceof Long?"putLong":"putString";R.call(tag,method,key,value);}
 @SuppressWarnings("unchecked") static Set<String> keys(Object t){return (Set<String>)R.call(t,"getAllKeys");}
 public static void load(Object m,Object tag){if(!R.yes(R.call(tag,"contains","ZomboidClansV1")))return;ClanState s=state(m);Object data=R.call(tag,"getCompound","ZomboidClansV1"),profiles=R.call(data,"getList","Profiles",10),wars=R.call(data,"getList","Wars",10);for(int i=0;i<((Number)R.call(profiles,"size")).intValue();i++){Object t=R.call(profiles,"getCompound",i);Profile p=s.profile((UUID)R.call(t,"getUUID","UUID"));p.motto=String.valueOf(R.call(t,"getString","Motto"));p.badge=String.valueOf(R.call(t,"getString","Badge"));p.doctrine=String.valueOf(R.call(t,"getString","Doctrine"));p.lastResult=String.valueOf(R.call(t,"getString","Result"));p.nexusIssued=R.yes(R.call(t,"getBoolean","NexusIssued"));p.nexusPlaced=R.yes(R.call(t,"getBoolean","NexusPlaced"));p.nexusPos=R.lng(R.call(t,"getLong","NexusPos"));p.nexusUpgrade=Math.max(0,Math.min(10,((Number)R.call(t,"getInt","NexusUpgrade")).intValue()));p.pveXp=((Number)R.call(t,"getInt","PveXp")).intValue();p.pveWins=((Number)R.call(t,"getInt","PveWins")).intValue();p.pveNext=R.lng(R.call(t,"getLong","PveNext"));p.offer=R.yes(R.call(t,"contains","PveOffer"))?((Number)R.call(t,"getInt","PveOffer")).intValue():-1;p.offerEnd=R.lng(R.call(t,"getLong","PveOfferEnd"));Object rewards=R.call(t,"getCompound","Rewards");for(String k:keys(rewards))p.rewards.put(k,((Number)R.call(rewards,"getInt",k)).intValue());Object cds=R.call(t,"getCompound","Cooldowns");for(String k:keys(cds))p.cooldowns.put(UUID.fromString(k),R.lng(R.call(cds,"getLong",k)));}
  for(int i=0;i<((Number)R.call(wars,"size")).intValue();i++){Object t=R.call(wars,"getCompound",i);War w=new War();w.id=(UUID)R.call(t,"getUUID","Id");w.a=(UUID)R.call(t,"getUUID","A");w.b=(UUID)R.call(t,"getUUID","B");w.siege=R.yes(R.call(t,"getBoolean","Siege"));w.ready=R.lng(R.call(t,"getLong","Ready"));w.end=R.lng(R.call(t,"getLong","End"));w.scoreA=((Number)R.call(t,"getInt","ScoreA")).intValue();w.scoreB=((Number)R.call(t,"getInt","ScoreB")).intValue();Object victims=R.call(t,"getList","Victims",10);for(int j=0;j<((Number)R.call(victims,"size")).intValue();j++){Object v=R.call(victims,"getCompound",j);UUID id=(UUID)R.call(v,"getUUID","Id");w.lastVictim.put(id,R.lng(R.call(v,"getLong","Time")));w.victimCount.put(id,((Number)R.call(v,"getInt","Count")).intValue());}w.objectives.addAll(keys(R.call(t,"getCompound","Objectives")));s.wars.put(w.id,w);}}
}
